gy3(){return"\u041e\u0431\u0430 \u0447\u0438\u0441\u043b\u0430 \u0432 \u043d\u0451\u043c \u0443\u043a\u043b\u0430\u0434\u0430\u044e\u0442\u0441\u044f, \u043d\u043e \u0438 \u0432 \u043c\u0435\u043d\u044c\u0448\u0435\u043c \u0442\u043e\u0436\u0435: \u0438\u0449\u0438 \u043d\u0430\u0438\u043c\u0435\u043d\u044c\u0448\u0435\u0435."},
gxS(){return"\u041d\u041e\u0414 \u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 \u043c\u0435\u043d\u044c\u0448\u0435\u0433\u043e \u0447\u0438\u0441\u043b\u0430; \u041d\u041e\u041a \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 \u0431\u043e\u043b\u044c\u0448\u0435\u0433\u043e."},
gyl(){return"\u041f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u0447\u0438\u0441\u0435\u043b \u2014 \u043e\u0431\u0449\u0435\u0435 \u043a\u0440\u0430\u0442\u043d\u043e\u0435, \u043d\u043e \u043d\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 \u043d\u0430\u0438\u043c\u0435\u043d\u044c\u0448\u0435\u0435: \u0440\u0430\u0437\u0434\u0435\u043b\u0438 \u0435\u0433\u043e \u043d\u0430 \u0438\u0445 \u041d\u041e\u0414."},
gym(){return"\u042d\u0442\u043e \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0437 \u0447\u0438\u0441\u043b\u043e \u0443\u043a\u043b\u0430\u0434\u0430\u0435\u0442\u0441\u044f; \u043e\u0441\u0442\u0430\u0442\u043e\u043a \u2014 \u044d\u0442\u043e \u0442\u043e, \u0447\u0442\u043e \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e."},
gy4(){return"\u042d\u0442\u043e \u0447\u0438\u0441\u043b\u043e \u0434\u0435\u043b\u0438\u0442\u0441\u044f \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 1 \u0438 \u043d\u0430 \u0441\u0435\u0431\u044f: \u043f\u0440\u043e\u0432\u0435\u0440\u044c \u043f\u0440\u043e\u0441\u0442\u044b\u0435 \u0447\u0438\u0441\u043b\u0430 \u0434\u043e \u0435\u0433\u043e \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u043e\u0433\u043e \u043a\u043e\u0440\u043d\u044f (2, 3, 5, 7, 11, 13, 17\u2026)."},
gy_(){return"\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438: \u0434\u043b\u044f 3 \u0438\u043b\u0438 9 \u0441\u043b\u043e\u0436\u0438 \u0446\u0438\u0444\u0440\u044b; \u0434\u043b\u044f 4 \u0441\u043c\u043e\u0442\u0440\u0438 \u043d\u0430 \u0434\u0432\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u0446\u0438\u0444\u0440\u044b; \u0434\u043b\u044f 6 \u2014 \u0447\u0451\u0442\u043d\u043e\u0435 \u0438 \u0434\u0435\u043b\u0438\u0442\u0441\u044f \u043d\u0430 3."},
gxC(){return"\u0427\u0438\u0441\u043b\u043e \u043f\u0435\u0440\u0435\u0434 \u0441\u043a\u043e\u0431\u043a\u0430\u043c\u0438 \u0443\u043c\u043d\u043e\u0436\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0432\u0441\u0451 \u0432\u043d\u0443\u0442\u0440\u0438: 3(x + 2) \u2014 \u044d\u0442\u043e 3x + 6, \u0430 \u043d\u0435 3x + 2."},
gye(){return"\u041f\u043b\u043e\u0449\u0430\u0434\u044c \u2014 \u044d\u0442\u043e \u043f\u043e\u0432\u0435\u0440\u0445\u043d\u043e\u0441\u0442\u044c: \u0434\u043b\u0438\u043d\u0430 \xd7 \u0448\u0438\u0440\u0438\u043d\u0430. \u0421\u0443\u043c\u043c\u0430 \u0441\u0442\u043e\u0440\u043e\u043d \u2014 \u044d\u0442\u043e \u043f\u0435\u0440\u0438\u043c\u0435\u0442\u0440."},
gyz(){return"\u0421\u0443\u043c\u043c\u0430 \u0443\u0433\u043b\u043e\u0432 \u0442\u0440\u0435\u0443\u0433\u043e\u043b\u044c\u043d\u0438\u043a\u0430 180\xb0, \u043f\u0440\u044f\u043c\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u2014 180\xb0, \u0430 \u0441\u0443\u043c\u043c\u0430 \u0443\u0433\u043b\u043e\u0432 \u0447\u0435\u0442\u044b\u0440\u0451\u0445\u0443\u0433\u043e\u043b\u044c\u043d\u0438\u043a\u0430 360\xb0."},
gyu(){return"\u041f\u043e \u041f\u0438\u0444\u0430\u0433\u043e\u0440\u0443: \u0432\u043e\u0437\u0432\u0435\u0434\u0438 \u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0432 \u043a\u0432\u0430\u0434\u0440\u0430\u0442, \u0441\u043b\u043e\u0436\u0438 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u044b, \u043f\u043e\u0442\u043e\u043c \u0438\u0437\u0432\u043b\u0435\u043a\u0438 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c."},
gxK(){return"\u041d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u043e\u0433\u043e \u043a\u043e\u0440\u043d\u044f: \u043d\u0430\u0439\u0434\u0438 \u0447\u0438\u0441\u043b\u043e, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u043f\u0440\u0438 \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0438 \u043d\u0430 \u0441\u0435\u0431\u044f \u0434\u0430\u0451\u0442 \u044d\u0442\u043e\u0442 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u043f\u043e \u041f\u0438\u0444\u0430\u0433\u043e\u0440\u0443 a\xb2 + b\xb2 \u2014 \u044d\u0442\u043e \u043a\u0432\u0430\u0434\u0440\u0430\u0442 \u0441\u0430\u043c\u043e\u0439 \u0434\u043b\u0438\u043d\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b)."},
