gzv(){return"\u041a\u0440\u0430\u0442\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0434\u043d\u043e\u043c\u0443 \u0438\u0437 \u0447\u0438\u0441\u0435\u043b"},
